-size:10px;margin-top:3px}.roster-row button{padding:8px 10px;border-radius:9px;background:#e6f1dd;color:#477451;font-size:10px;font-weight:900}.log{height:45px;color:#617d66;font-size:11px;font-weight:750;text-align:center;padding:13px 0}.battle-arena{border-radius:16px;background:linear-gradient(155deg,#dcefd1,#eff4dc 55%,#f6ead3);padding:17px 14px 8px;position:relative;overflow:hidden;margin-bottom:10px}.combatants{display:flex;justify-content:space-around;align-items:flex-end;min-height:118px}.combatant{text-align:center;width:30%;font-size:34px;position:relative}.combatant small{display:block;font-size:9px;font-weight:900;color:#4e7052;margin-top:4px}.combatant .combat-hp{height:5px;background:#fff;border-radius:5px;margin:6px auto;width:75%;overflow:hidden}.combat-hp i{display:block;height:100%;background:#83b86d;transition:width .25s}.battle-banner{position:absolute;top:10px;left:0;right:0;text-align:center;font-size:9px;font-weight:900;letter-spacing:1px;color:#62826a}.battle-actions{display:flex;gap:8px}.battle-actions button{flex:1;background:#e7f1df;border-radius:11px;padding:11px;font-size:11px;font-weight:900;color:#477052}.battle-actions .primary{background:#3e795c;color:white}.battle-result{font-size:12px;line-height:1.5;color:#687b6d;background:#f1f5ed;padding:12px;border-radius:12px;margin:10px 0}
