Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -17,4 +17,36 @@
 <section class="mini-battle"><div class="battle-top"><div><div class="battle-kicker">✦ Friendly sparring</div><div class="battle-title" id="battleTitle">Ready when you are</div></div><div class="battle-count" id="battleCount">3 vs 1</div></div><button class="battle-btn" id="battleButton">⚔ &nbsp; Start a practice duel</button></section>
 <nav class="bottom-nav"><button class="nav-btn selected" data-tab="Explore"><span>🧭</span>Explore</button><button class="nav-btn" data-tab="Friends"><span>🫧</span>Friends</button><button class="nav-btn" data-tab="Journal"><span>📖</span>Journal</button><button class="nav-btn" data-tab="Style"><span>🎨</span>Style</button></nav></aside></div></main>
 <div class="modal-backdrop" id="modalBackdrop" hidden><section class="modal" id="modal"></section></div>
 <script>
+const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),card=document.querySelector('#worldCard');
+const palette=[{name:'Sunmeadow',sky:'#b8df9b',ground:'#9acb7e',deep:'#83b773',path:'#e5d09c',accent:'#f2d879',accent2:'#d7edf0',weather:'☀️',kicker:'✦ EXPLORING'},{name:'Whisperwood',sky:'#b2d8af',ground:'#78ae83',deep:'#54866b',path:'#c5bd89',accent:'#d8e9ae',accent2:'#d4d8ee',weather:'🌿',kicker:'✦ EXPLORING'},{name:'Ember Ridge',sky:'#f0c28e',ground:'#bd9875',deep:'#96785f',path:'#e2b477',accent:'#edbd7e',accent2:'#dce4c2',weather:'🌤️',kicker:'✦ EXPLORING'}];
+let region=0,player={x:.43,y:.53,skin:2,hair:0,gender:'They',hairColor:0,outfit:0,name:'Moss'},zoom=1,keys={},moving=null,encounter=null,questDone=false,berries=8,shards=24,logTimer=0;
+let friends=[{name:'Pipkin',kind:'Leaf',emoji:'🐸',level:4,hp:100,color:'#b7d985',atk:12},{name:'Cindercub',kind:'Ember',emoji:'🦊',level:3,hp:86,color:'#f2bd77',atk:10},{name:'Mallow',kind:'Cloud',emoji:'🐑',level:3,hp:92,color:'#c8dded',atk:9}];
+const wilds=[{name:'Dewdrop',emoji:'🦋',hp:65,atk:7,kind:'Breeze'},{name:'Mossbit',emoji:'🐢',hp:76,atk:8,kind:'Moss'},{name:'Pebblit',emoji:'🦔',hp:88,atk:9,kind:'Earth'}];
+let wild={x:.73,y:.47,active:true,idx:0};
+function resize(){const r=card.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;canvas.style.width=r.width+'px';canvas.style.height=r.height+'px';ctx.setTransform(d,0,0,d,0,0)}window.addEventListener('resize',resize);resize();
+function hash(n){let x=Math.sin(n*127.1+region*51)*43758.5453;return x-Math.floor(x)}
+function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
+function drawFlower(x,y,r,col){ctx.fillStyle=col;for(let i=0;i<5;i++){let a=i*Math.PI*2/5;ctx.beginPath();ctx.arc(x+Math.cos(a)*r*.7,y+Math.sin(a)*r*.7,r*.48,0,7);ctx.fill()}ctx.fillStyle='#e7c56e';ctx.beginPath();ctx.arc(x,y,r*.33,0,7);ctx.fill()}
+function drawTree(x,y,s,c){ctx.fillStyle='#44664a33';ctx.beginPath();ctx.ellipse(x,y+s*.42,s*.8,s*.22,0,0,7);ctx.fill();ctx.fillStyle='#7d6248';ctx.fillRect(x-s*.09,y+s*.02,s*.18,s*.5);ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,s*.49,0,7);ctx.arc(x-s*.25,y+s*.09,s*.35,0,7);ctx.arc(x+s*.28,y+s*.11,s*.34,0,7);ctx.fill();ctx.fillStyle='#ffffff24';ctx.beginPath();ctx.arc(x-s*.12,y-s*.12,s*.22,0,7);ctx.fill()}
+function drawPath(w,h){ctx.beginPath();ctx.moveTo(w*.12,h*.82);ctx.bezierCurveTo(w*.34,h*.7,w*.26,h*.57,w*.49,h*.51);ctx.bezierCurveTo(w*.74,h*.42,w*.64,h*.29,w*.91,h*.2);ctx.lineTo(w*.94,h*.36);ctx.bezierCurveTo(w*.74,h*.47,w*.85,h*.58,w*.57,h*.65);ctx.bezierCurveTo(w*.36,h*.74,w*.47,h*.8,w*.17,h*.98);ctx.closePath();ctx.fillStyle=palette[region].path;ctx.fill();ctx.globalAlpha=.22;ctx.strokeStyle='#fff9d6';ctx.lineWidth=3;ctx.stroke();ctx.globalAlpha=1}
+function drawCreature(x,y,emoji,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#34523735';ctx.beginPath();ctx.ellipse(0,14,18,6,0,0,7);ctx.fill();ctx.fillStyle='#ffffffb8';ctx.beginPath();ctx.arc(0,0,19,0,7);ctx.fill();ctx.font='27px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(emoji,0,1);ctx.restore()}
+function drawPlayer(x,y){ctx.save();ctx.translate(x,y);ctx.fillStyle='#304d3c35';ctx.beginPath();ctx.ellipse(0,16,16,5,0,0,7);ctx.fill();ctx.fillStyle=['#f5c99c','#e7ae7d','#bd7954','#704631','#e8cbb0'][player.skin];ctx.beginPath();ctx.arc(0,-5,9,0,7);ctx.fill();ctx.fillStyle=['#546b40','#d5a866','#58423c','#4f7790'][player.outfit];ctx.beginPath();ctx.roundRect(-9,2,18,16,6);ctx.fill();ctx.fillStyle=['#49342d','#382b31','#d8b15e','#514136'][player.hairColor];ctx.beginPath();ctx.arc(0,-9,10,Math.PI,Math.PI*2);ctx.lineTo(9,-4);ctx.quadraticCurveTo(2,-8,0,-4);ctx.lineTo(-9,-5);ctx.closePath();ctx.fill();ctx.fillStyle='#26362d';ctx.beginPath();ctx.arc(-3,-5,1,0,7);ctx.arc(3,-5,1,0,7);ctx.fill();ctx.restore()}
+function draw(){const w=card.clientWidth,h=card.clientHeight;ctx.clearRect(0,0,w,h);let p=palette[region];let grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,p.sky);grad.addColorStop(.63,p.ground);grad.addColorStop(1,p.deep);ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);
+// rolling hills
+for(let i=0;i<5;i++){let y=h*(.18+i*.105)+Math.sin(i*3+region)*13;ctx.fillStyle=[p.deep,p.ground,p.deep,p.ground,p.deep][i]+'58';ctx.beginPath();ctx.moveTo(0,h);ctx.lineTo(0,y+18);for(let x=0;x<=w+30;x+=30)ctx.lineTo(x,y+Math.sin(x*.012+i*2)*16);ctx.lineTo(w,h);ctx.closePath();ctx.fill()}
+drawPath(w,h);
+// pond / glimmer
+if(region===0){ctx.fillStyle='#94c9cb';ctx.beginPath();ctx.ellipse(w*.83,h*.77,Math.min(w*.11,86),h*.055,-.18,0,7);ctx.fill();ctx.strokeStyle='#e5ffff8c';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(w*.83,h*.77,Math.min(w*.08,58),h*.03,-.18,0,7);ctx.stroke()}
+for(let i=0;i<34;i++){let x=hash(i+1)*w,y=hash(i+78)*h,s=5+hash(i+103)*8;if(y<h*.2||Math.hypot((x/w-player.x)*w,(y/h-player.y)*h)<55)continue;if(i%4===0)drawTree(x,y,s*1.6,[region===1?'#4b7f5a':'#729b5b','#668d57','#96b973'][i%3]);else drawFlower(x,y,s*.42,[p.accent,p.accent2,'#fff0c4'][i%3])}
+// footpath flecks
+for(let i=0;i<22;i++){let x=w*(.12+hash(i+142)*.78),y=h*(.25+hash(i+170)*.62);ctx.fillStyle='#fff8d566';ctx.beginPath();ctx.ellipse(x,y,2,1,0,0,7);ctx.fill()}
+// area gate
+let gx=w*.92,gy=h*.28;rounded(gx-22,gy-32,44,55,18,'#8a6d4e');rounded(gx-16,gy-27,32,49,14,'#e1cd9b');ctx.fillStyle='#a1cc85';ctx.beginPath();ctx.arc(gx,gy-3,11,Math.PI,0);ctx.fill();ctx.fillRect(gx-11,gy-3,22,22);ctx.fillStyle='#f9edbf';ctx.beginPath();ctx.arc(gx,gy+4,2,0,7);ctx.fill();
+let px=player.x*w,py=player.y*h;drawCreature(px-40,py+27,friends[0].emoji,.76);drawCreature(px-62,py+46,friends[1].emoji,.65);drawCreature(px-24,py+51,friends[2].emoji,.63);if(wild.active){let wx=wild.x*w,wy=wild.y*h;drawCreature(wx,wy,wilds[wild.idx].emoji,1.02);ctx.fillStyle='#fff';ctx.font='10px system-ui';ctx.textAlign='center';ctx.fillText('✦ wildling',wx,wy-28)}drawPlayer(px,py);
+// top horizon soft wash
+let shade=ctx.createLinearGradient(0,0,0,h*.22);shade.addColorStop(0,'#ffffff2c');shade.addColorStop(1,'#ffffff00');ctx.fillStyle=shade;ctx.fillRect(0,0,w,h*.22);
+}
+function tick(){let dx=0,dy=0;if(keys.ArrowUp||keys.w||moving==='up')dy=-1;if(keys.ArrowDown||keys.s||moving==='down')dy=1;if(keys.ArrowLeft||keys.a||moving==='left')dx=-1;if(keys.ArrowRight||keys.d||moving==='right')dx=1;if(dx||dy){let len=Math.hypot(dx,dy);player.x+=dx/len*.0025;player.y+=dy/len*.0025;player.x=Math.max(.08,Math.min(.94,player.x));player.y=Math.max(.17,Math.min(.88,player.y));if(player.x>.88&&player.y<.46)changeRegion((region+1)%3);if(player.x*wSafe()>wild.x*wSafe()-55&&Math.abs(player.y-wild.y)<.12&&wild.active)startEncounter('wild');}draw();requestAnimationFrame(tick)}function wSafe(){return card.clientWidth||1}requestAnimationFrame(tick);
+function changeRegion(next){region=next;player.x=.15;player.y=.47;wild={x:.68,y:.49,active:true,idx:(wild.idx+1)%wilds.length};document.querySelector('#zoneName').textContent=palette[region].name;document.querySelector('#gateLabel').textContent='✧ '+['Whisperwood path','Ember Ridge trail','Sunmeadow path'][region];document.querySelector('.weather-chip span').textContent=palette[region].weather;toast('Welcome to '+palette[region].name+'!');}
+function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(logTimer);logTimer=setTimeout(()=>t.classList.remove('show'),2100)}

input.newString:
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(logTimer);logTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function renderParty(){document.querySelector('#partyCount').textContent=friends.length+' / 6';document.querySelector('#battleCount').textContent=friends.length+' vs 1';document.querySelector('#partyList').innerHTML=friends.slice(0,3).map((f,i)=>`<div class="creature ${i===0?'active':''}" data-friend="${i}"><div class="creature-emoji">${f.emoji}</div><div class="creature-info"><div class="creature-name">${f.name}</div><div class="creature-sub">${f.kind} friend · Lv. ${f.level}</div><div class="hp-track"><i style="width:${f.hp}%"></i></div></div><div class="level">♥ ${f.hp}</div></div>`).join('');document.querySelectorAll('.creature').forEach(el=>el.onclick=()=>{document.querySelectorAll('.creature').forEach(x=>x.classList.remove('active'));el.classList.add('active');toast(friends[+el.dataset.friend].name+' is leading the way')})}renderParty();
function openModal(html){const b=document.querySelector('#modalBackdrop');document.querySelector('#modal').innerHTML=html;b.hidden=false;document.querySelector('#modal').querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal)}function closeModal(){document.querySelector('#modalBackdrop').hidden=true}document.querySelector('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
function startEncounter(type='wild'){if(encounter)return;encounter={wild:{...wilds[wild.idx],hp:wilds[wild.idx].hp},type,turn:0,active:true};if(type==='duel')encounter.wild={name:'Rival Rowan',emoji:'🧑🏻‍🌾',hp:100,atk:9,kind:'Trainer'};openBattleModal();fightTick()}
function openBattleModal(){let foe=encounter.wild;openModal(`<div class="modal-head"><div><div class="eyebrow">A friendly little skirmish</div><div class="modal-title">${encounter.type==='duel'?'Practice duel':'A wild '+foe.name+'!'}</div><div class="modal-copy">Your whole party joins in. Sit back and cheer them on!</div></div><button class="close-btn" data-close>×</button></div><div class="battle-arena"><div class="battle-banner" id="battleBanner">THE PARTY IS READY</div><div class="combatants"><div class="combatant"><span>${friends[0].emoji}</span><small>${friends[0].name}</small><div class="combat-hp"><i style="width:${friends[0].hp}%"></i></div></div><div class="combatant"><span>${friends[1].emoji}</span><small>${friends[1].name}</small><div class="combat-hp"><i style="width:${friends[1].hp}%"></i></div></div><div class="combatant" id="foeFigure"><span>${foe.emoji}</span><small>${foe.name}</small><div class="combat-hp"><i id="foeHp" style="width:100%"></i></div></div></div></div><div class="log" id="battleLog">The friends circle around their new acquaintance…</div><div class="battle-actions"><button id="cheerBtn">💚 Cheer them on</button><button class="primary" id="battleAction">✨ Auto-battle</button></div><div id="battleResult"></div>`);document.querySelector('#cheerBtn').onclick=()=>toast('Your friends feel braver!');document.querySelector('#battleAction').onclick=()=>{if(!encounter)return;encounter.active=!encounter.active;document.querySelector('#battleAction').textContent=encounter.active?'⏸ Pause':'▶ Resume';if(encounter.active)fightTick()}}
function fightTick(){if(!encounter||!encounter.active)return;let e=encounter;setTimeout(()=>{if(encounter!==e||!e.active)return;e.turn++;let fighter=friends[(e.turn-1)%friends.length],damage=fighter.atk+Math.floor(Math.random()*7);e.wild.hp-=damage;let log=document.querySelector('#battleLog'),hp=document.querySelector('#foeHp'),banner=document.querySelector('#battleBanner');if(!log)return;hp.style.width=Math.max(0,e.wild.hp/(e.type==='duel'?100:wilds[wild.idx].hp)*100)+'%';banner.textContent=fighter.name.toUpperCase()+' USES A FRIENDLY BOP!';log.textContent=fighter.emoji+' '+fighter.name+' gives a joyful little bop for '+damage+'!';document.querySelector('#foeFigure').style.transform='translateX(7px)';setTimeout(()=>{let f=document.querySelector('#foeFigure');if(f)f.style.transform='translateX(0)'},130);if(e.wild.hp<=0){winBattle();return}if(e.turn%3===0){let idx=Math.floor(Math.random()*friends.length);friends[idx].hp=Math.max(30,friends[idx].hp-e.wild.atk);renderParty();let hpBars=document.querySelectorAll('.combat-hp i');if(hpBars[idx])hpBars[idx].style.width=friends[idx].hp+'%';log.textContent=e.wild.name+' boops '+friends[idx].name+' back. Still friends!'}fightTick()},850)}
