utfit===i?'selected':''}" data-outfit="${i}">${x}</button>`).join('')}</div></div><button class="save-btn" id="saveStyle">Save my style ✨</button>`);let m=document.querySelector('#modal');m.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{player.skin=+b.dataset.skin;m.querySelectorAll('[data-skin]').forEach(x=>x.classList.toggle('selected',x===b));m.querySelector('#previewFace').textContent=avatarEmoji()});m.querySelectorAll('[data-hair]').forEach(b=>b.onclick=()=>{player.hair=+b.dataset.hair;m.querySelectorAll('[data-hair]').forEach(x=>x.classList.toggle('selected',x===b))});m.querySelectorAll('[data-haircolor]').forEach(b=>b.onclick=()=>{player.hairColor=+b.dataset.haircolor;m.querySelectorAll('[data-haircolor]').forEach(x=>x.classList.toggle('selected',x===b))});m.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{player.gender=b.dataset.gender;m.querySelectorAll('[data-gender]').forEach(x=>x.classList.toggle('selected',x===b))});m.querySelectorAll('[data-outfit]').forEach(b=>b.onclick=()=>{player.outfit=+b.dataset.outfit;m.querySelectorAll('[data-outfit]').forEach(x=>x.classList.toggle('selected',x===b))});m.querySelector('#saveStyle').onclick=()=>{player.name=m.querySelector('#nameInput').value.trim()||'Moss';document.querySelector('#playerName').textContent=player.name;document.querySelector('#avatarMini').textContent=avatarEmoji();closeModal();toast('Looking lovely, '+player.name+'!')}}
document.querySelector('#customize').onclick=showCustomize;
document.querySelector('#battleButton').onclick=()=>startEncounter('duel');
document.querySelector('#zoomIn').onclick=()=>{zoom=Math.min(1.5,zoom+.1);toast('Map zoom '+Math.round(zoom*100)+'%')};document.querySelector('#zoomOut').onclick=()=>{zoom=Math.max(.8,zoom-.1);toast('Map zoom '+Math.round(zoom*100)+'%')};document.querySelector('#centerMap').onclick=()=>{player.x=.43;player.y=.53;toast('Back to your friends')};
canvas.addEventListener('pointerdown',e=>{let r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;if(x>.84&&y<.45){changeRegion((region+1)%3);return}if(wild.active&&Math.hypot((x-wild.x)*r.width,(y-wild.y)*r.height)<70){startEncounter('wild');return}player.x=Math.max(.1,Math.min(.88,x));player.y=Math.max(.2,Math.min(.85,y));if(wild.active&&Math.hypot((player.x-wild.x)*r.width,(player.y-wild.y)*r.height)<125)startEncounter('wild')});
