document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav-btn').forEach(x=>x.classList.toggle('selected',x===b));if(b.dataset.tab==='Style')showCustomize();else if(b.dataset.tab==='Friends')openModal(`<div class="modal-head"><div><div class="eyebrow">Your growing little family</div><div class="modal-title">Friends (${friends.length}/6)</div><div class="modal-copy">Your whole party joins every auto-battle together.</div></div><button class="close-btn" data-close>×</button></div><div class="modal-roster">${friends.map(f=>`<div class="roster-row"><div class="creature-emoji">${f.emoji}</div><div class="roster-copy"><b>${f.name}</b><small>${f.kind} friend · Level ${f.level} · ${f.hp}% energy</small></div><button data-cheer="${f.name}">Say hi</button></div>`).join('')}</div>`);else if(b.dataset.tab==='Journal')openModal(`<div class="modal-head"><div><div class="eyebrow">Memories from your travels</div><div class="modal-title">Little field journal</div></div><button class="close-btn" data-close>×</button></div><div class="battle-result">🌼 <b>Sunmeadow</b><br>A sunny place to begin. The wildlings here are gentle and curious.<br><br>🌳 <b>Whisperwood</b><br>Follow the little stone path through the trees.<br><br>⛰️ <b>Ember Ridge</b><br>Warm golden hills, with a bright horizon.</div><div class="modal-copy">${questDone?'You made a new friend today. That is a lovely adventure.':'Your quest: meet a wildling and invite them along.'}</div>`)});
document.querySelector('#partyList').addEventListener('click',e=>{let b=e.target.closest('[data-cheer]');if(b)toast('A little hello for '+b.dataset.cheer+'!')});
document.querySelector('#gateLabel').onclick=()=>changeRegion((region+1)%3);
</script>
</body>
